'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '../context/AuthContext';
import styles from '../page.module.css';
import Link from 'next/link';

interface Transaction {
  id: string;
  type: string;
  amount: number;
  description: string;
  createdAt: string;
  account: { accountNumber: string };
}

export default function History() {
  const { token, isAuthenticated, logout } = useAuth();
  const router = useRouter();
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!isAuthenticated) {
      router.push('/login');
      return;
    }

    fetch(`${process.env.NEXT_PUBLIC_API_URL}/api/transactions/history`, {
      headers: { 'Authorization': `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => {
        setTransactions(data);
        setLoading(false);
      });
  }, [isAuthenticated, router, token]);

  if (!isAuthenticated) return null;

  return (
    <div className={styles.container}>
      <header className={styles.header}>
        <div className={styles.logo}>Bank Modern</div>
        <nav className={styles.nav}>
          <Link href="/dashboard">Dashboard</Link>
          <Link href="/transfer">Transfer</Link>
          <Link href="/history">History</Link>
          <a href="#" onClick={(e) => { e.preventDefault(); logout(); }}>Logout</a>
        </nav>
      </header>

      <main className={styles.main}>
        <section className={styles.hero} style={{ marginBottom: '2rem' }}>
          <h1>Transaction History</h1>
        </section>

        <section className={styles.dashboard} style={{ display: 'block' }}>
          {loading ? (
            <p>Loading transactions...</p>
          ) : transactions.length === 0 ? (
             <p>No transactions found.</p>
          ) : (
            <div style={{ background: 'white', borderRadius: '12px', padding: '1rem', boxShadow: '0 10px 20px rgba(0,0,0,0.05)' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                <thead>
                  <tr style={{ borderBottom: '2px solid #f4f7f6' }}>
                    <th style={{ padding: '1rem', color: '#16213e' }}>Date</th>
                    <th style={{ padding: '1rem', color: '#16213e' }}>Account</th>
                    <th style={{ padding: '1rem', color: '#16213e' }}>Type</th>
                    <th style={{ padding: '1rem', color: '#16213e' }}>Description</th>
                    <th style={{ padding: '1rem', color: '#16213e' }}>Amount</th>
                  </tr>
                </thead>
                <tbody>
                  {transactions.map(tx => (
                    <tr key={tx.id} style={{ borderBottom: '1px solid #f4f7f6' }}>
                      <td style={{ padding: '1rem' }}>{new Date(tx.createdAt).toLocaleDateString()}</td>
                      <td style={{ padding: '1rem' }}>{tx.account.accountNumber}</td>
                      <td style={{ padding: '1rem' }}>
                        <span style={{ 
                          padding: '0.25rem 0.5rem', 
                          borderRadius: '4px', 
                          fontSize: '0.85rem',
                          background: tx.type === 'TRANSFER_IN' ? '#d4edda' : '#f8d7da',
                          color: tx.type === 'TRANSFER_IN' ? '#155724' : '#721c24'
                        }}>
                          {tx.type}
                        </span>
                      </td>
                      <td style={{ padding: '1rem' }}>{tx.description}</td>
                      <td style={{ padding: '1rem', fontWeight: 'bold' }}>
                         {tx.type === 'TRANSFER_OUT' ? '-' : '+'}${tx.amount.toFixed(2)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      </main>
    </div>
  );
}
